import type { Readable } from 'node:stream'

export interface PutMeta {
  contentType: string
  /** Exact byte length of the stream (S3 needs it up front). */
  size: number
}

export interface StoredObject {
  stream: Readable
  size: number
}

/**
 * Where file bodies live. Keys are generated by the server (`tasks/<taskId>/<uuid>`), never taken
 * from user input; drivers still refuse anything that is not a plain relative key.
 */
export interface FileStorage {
  put(key: string, body: Readable, meta: PutMeta): Promise<void>
  /** Throws StorageNotFoundError when there is no such object. */
  get(key: string): Promise<StoredObject>
  /** Idempotent: deleting a missing object is not an error. */
  delete(key: string): Promise<void>
}

export class StorageNotFoundError extends Error {
  constructor(key: string) {
    super(`Stored object not found: ${key}`)
    this.name = 'StorageNotFoundError'
  }
}

// Segments of latin letters, digits, dash and underscore separated by single slashes.
const KEY = /^[A-Za-z0-9_-]+(\/[A-Za-z0-9_-]+)*$/

export function assertStorageKey(key: string): void {
  if (key.length > 300 || !KEY.test(key)) throw new Error(`Invalid storage key: ${JSON.stringify(key)}`)
}
